// Si no tenemos repo_id definido, lo obtenemos automáticamente del catálogo
if (!pm.collectionVariables.get("repo_id") && !pm.variables.get("repo_id")) {
    pm.sendRequest({
        url: pm.variables.get("baseUrl") + "/api/v1/repositories?size=1",
        method: "GET"
    }, function (err, res) {
        if (!err && res.code === 200) {
            const data = res.json().data;
            if (data && data.length > 0) {
                pm.variables.set("repo_id", data[0].id);
            }
        }
    });
}

