pm.test("Cada repositorio cumple estrictamente con el contrato y tipos de datos", function () {
    const data = pm.response.json().data;
    const maintenanceLevels = ["ACTIVE", "MODERATE", "AT_RISK", "ARCHIVED", null];
    const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

    data.forEach((repo, index) => {
        // 1. Campos de texto obligatorios
        pm.expect(repo.id, `repo[${index}].id debe ser un UUID válido`).to.match(uuidRegex);
        pm.expect(repo.fullName, `repo[${index}].fullName debe ser string no vacío`).to.be.a("string").and.not.empty;
        pm.expect(repo.name, `repo[${index}].name debe ser string no vacío`).to.be.a("string").and.not.empty;

        // 2. Campos opcionales (string o null)
        pm.expect(repo.description === null || typeof repo.description === "string", `repo[${index}].description debe ser string o null`).to.be.true;
        pm.expect(repo.primaryLanguage === null || typeof repo.primaryLanguage === "string", `repo[${index}].primaryLanguage debe ser string o null`).to.be.true;
        pm.expect(repo.licenseSpdx === null || typeof repo.licenseSpdx === "string", `repo[${index}].licenseSpdx debe ser string o null`).to.be.true;

        // 3. Estrellas (entero >= 0)
        pm.expect(repo.stars, `repo[${index}].stars debe ser un número entero`).to.be.a("number");
        pm.expect(repo.stars, `repo[${index}].stars debe ser >= 0`).to.be.at.least(0);

        // 4. Métricas de salud y mantenimiento
        if (repo.healthScore !== null) {
            pm.expect(repo.healthScore, `repo[${index}].healthScore debe estar entre 0 y 100`).to.be.within(0, 100);
        }
        pm.expect(maintenanceLevels, `repo[${index}].maintenanceLevel tiene valor inválido`).to.include(repo.maintenanceLevel);

        // 5. Categorías (array de objetos con slug y name)
        pm.expect(repo.categories, `repo[${index}].categories debe ser un array`).to.be.an("array");
        repo.categories.forEach((cat) => {
            pm.expect(cat).to.have.property("slug").that.is.a("string");
            pm.expect(cat).to.have.property("name").that.is.a("string");
        });

        // 6. Fecha de último commit (formato ISO 8601 o null)
        if (repo.lastCommitAt !== null) {
            pm.expect(repo.lastCommitAt).to.be.a("string");
            pm.expect(isNaN(Date.parse(repo.lastCommitAt)), `repo[${index}].lastCommitAt debe ser fecha ISO válida`).to.be.false;
        }
    });
});

